CREATE TABLE `Journal` (`id` VARCHAR(36) NOT NULL,`ownerId` VARCHAR(36) NOT NULL,`title` VARCHAR(160) NOT NULL,`description` TEXT NOT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,INDEX `Journal_ownerId_updatedAt_idx`(`ownerId`,`updatedAt`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `JournalEntry` (`id` VARCHAR(36) NOT NULL,`journalId` VARCHAR(36) NOT NULL,`title` VARCHAR(200) NULL,`content` LONGTEXT NOT NULL,`entryDate` DATETIME(3) NOT NULL,`published` BOOLEAN NOT NULL DEFAULT false,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,INDEX `JournalEntry_journalId_entryDate_idx`(`journalId`,`entryDate`),INDEX `JournalEntry_published_entryDate_idx`(`published`,`entryDate`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `JournalShare` (`journalId` VARCHAR(36) NOT NULL,`userId` VARCHAR(36) NOT NULL,`permission` ENUM('NONE','READ','COMMENT','WRITE') NOT NULL,INDEX `JournalShare_userId_idx`(`userId`),PRIMARY KEY (`journalId`,`userId`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `JournalEntryShare` (`entryId` VARCHAR(36) NOT NULL,`userId` VARCHAR(36) NOT NULL,`permission` ENUM('NONE','READ','COMMENT','WRITE') NOT NULL,INDEX `JournalEntryShare_userId_idx`(`userId`),PRIMARY KEY (`entryId`,`userId`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `JournalComment` (`id` VARCHAR(36) NOT NULL,`entryId` VARCHAR(36) NOT NULL,`authorId` VARCHAR(36) NOT NULL,`content` TEXT NOT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,INDEX `JournalComment_entryId_createdAt_idx`(`entryId`,`createdAt`),INDEX `JournalComment_authorId_idx`(`authorId`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `Journal` ADD CONSTRAINT `Journal_ownerId_fkey` FOREIGN KEY (`ownerId`) REFERENCES `User`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `JournalEntry` ADD CONSTRAINT `JournalEntry_journalId_fkey` FOREIGN KEY (`journalId`) REFERENCES `Journal`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `JournalShare` ADD CONSTRAINT `JournalShare_journalId_fkey` FOREIGN KEY (`journalId`) REFERENCES `Journal`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `JournalShare` ADD CONSTRAINT `JournalShare_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `JournalEntryShare` ADD CONSTRAINT `JournalEntryShare_entryId_fkey` FOREIGN KEY (`entryId`) REFERENCES `JournalEntry`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `JournalEntryShare` ADD CONSTRAINT `JournalEntryShare_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `JournalComment` ADD CONSTRAINT `JournalComment_entryId_fkey` FOREIGN KEY (`entryId`) REFERENCES `JournalEntry`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `JournalComment` ADD CONSTRAINT `JournalComment_authorId_fkey` FOREIGN KEY (`authorId`) REFERENCES `User`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
